1	/** Ship speeds are per world step, and the world steps 20 times a second (§15). */
2	export const WORLD_STEPS_PER_SECOND = 20;
3	
4	/**
5	 * Sailing (§3): acceleration, braking and turning, tuned for generous handling. Speeds are sub-units per 20 Hz world
6	 * step; accelerations are the change in speed per world step. The sea is compact (§3's travel times at three tiles a
7	 * second) and drawn at 24 px a tile, so on screen a ship handles as it did at five tiles a second and 16 px: about
8	 * as fast in pixels, as quick to full speed and to a stop, and turning in about as wide a circle.
9	 */
10	export interface ShipTuning {
11	  /** Full throttle: 39 sub-units per world step is 780 a second, 3.05 tiles a second. */
