1	import { isNavigable, type Dock, type ShipTuning } from "@pirate-sea-race/content";
2	import type { SimulationConfig } from "./config.js";
3	import { divTrunc } from "./fixed.js";
4	import { HEADING_DX, HEADING_DY, HEADING_SCALE, normalizeHeading } from "./heading.js";
5	import { AXIS_SCALE, INTERACT_BUTTON, sanitizeInput, type PlayerInput } from "./input.js";
6	import { NOT_DOCKED, tileCentre, WORLD_STEP_INTERVAL, type MatchState, type ShipState } from "./state.js";
7	
8	/**
9	 * Held inputs by ship id. A ship without an entry sails as neutral input, except that a moored ship keeps the throttle
10	 * it moored with (`mooredThrottle`): a missing entry is no input at all (the server leaves it out when a player's input
11	 * lapsed), so it cannot release that throttle, and the player's unchanged held keys do not cast off when they resume.
12	 */
13	export type StepInputs = Readonly<Record<string, PlayerInput>>;
14	
15	export function isWorldStep(frame: number): boolean {
16	  return frame % WORLD_STEP_INTERVAL === 0;
17	}
18	
19	/**
20	 * Advances the match clock by one 60 Hz step and returns the new state. World logic (sailing) runs only when the new
21	 * frame is a multiple of WORLD_STEP_INTERVAL. The input state is never mutated.
22	 */
23	export function step(config: SimulationConfig, state: MatchState, inputs: StepInputs): MatchState {
24	  const frame = state.frame + 1;
25	  if (!isWorldStep(frame)) return { ...state, frame };
26	  return {
27	    ...state,
28	    frame,
29	    worldTick: state.worldTick + 1,
30	    ships: state.ships.map((ship) => {
31	      const input = inputs[ship.id];
32	      return input === undefined && ship.dock !== NOT_DOCKED ? ship : sail(config, ship, sanitizeInput(input));
33	    }),
34	  };
35	}
36	
37	/**
38	 * One world step of one ship (§3). The throttle (`-moveY`) accelerates, brakes or reverses; `moveX` turns the
39	 * heading; the ship then moves along its heading and stops or slides against land, shoals and the map edge.
40	 *
41	 * Docking: interact near a dock moors the ship there (at the dock tile's centre, speed 0) at any speed, if its hull
42	 * could sail straight there. Neither speed nor throttle matters, so a ship driven at its dock with ahead and interact
43	 * held moors on the first step it starts within reach, from any angle. A moored ship stays put while interact is held,
44	 * without throttle, or while the throttle it moored with is still held; releasing that throttle and then any throttle
45	 * (or the other direction) casts off and sails in the same step.
46	 */
47	export function sail(config: SimulationConfig, ship: ShipState, input: PlayerInput): ShipState {
48	  const tuning = config.ship;
49	  const throttle = -input.moveY;
50	  const interact = (input.buttons & INTERACT_BUTTON) !== 0;
51	  const direction = Math.sign(throttle);
52	  let dock = ship.dock;
53	  if (dock !== NOT_DOCKED) {
54	    if (direction === 0 || interact || direction === ship.mooredThrottle) {
55	      const mooredThrottle = direction === 0 ? 0 : ship.mooredThrottle;
56	      return ship.speed === 0 && ship.mooredThrottle === mooredThrottle ? ship : { ...ship, speed: 0, mooredThrottle };
57	    }
58	    dock = NOT_DOCKED;
59	  } else if (interact) {
60	    const berth = dockInReach(config, ship.x, ship.y);
61	    if (berth !== undefined) {
62	      return { ...ship, ...tileCentre(config, berth.tileX, berth.tileY), speed: 0, dock: berth.id, mooredThrottle: direction };
63	    }
64	  }
65	
66	  const heading = normalizeHeading(ship.heading + Math.sign(input.moveX) * tuning.turnRate);
67	  const speed = nextSpeed(tuning, ship.speed, throttle);
68	  const dx = divTrunc(speed * HEADING_DX[heading]!, HEADING_SCALE);
69	  const dy = divTrunc(speed * HEADING_DY[heading]!, HEADING_SCALE);
70	  const x = sweepX(config, ship.x, ship.y, dx);
71	  const y = sweepY(config, x, ship.y, dy);
72	  // Blocked on every axis it tried to move along: the ship has run aground and stops. Blocked on one axis only, it
73	  // slides along the obstacle on the other.
74	  const aground = (dx !== 0 || dy !== 0) && x === ship.x && y === ship.y;
75	  return { ...ship, x, y, heading, speed: aground ? 0 : speed, dock, mooredThrottle: 0 };
76	}
77	
78	/** The speed after one world step of throttle in [-AXIS_SCALE, AXIS_SCALE] (positive forward). */
79	export function nextSpeed(tuning: ShipTuning, speed: number, throttle: number): number {
80	  if (throttle > 0) {
81	    if (speed < 0) return Math.min(speed + tuning.braking, 0);
82	    const target = divTrunc(tuning.maxSpeed * throttle, AXIS_SCALE);
83	    return speed < target ? Math.min(speed + tuning.acceleration, target) : Math.max(speed - tuning.drag, target);
84	  }
85	  if (throttle < 0) {
86	    // Down brakes a ship under way, and reverses slowly from a stop.
87	    if (speed > 0) return Math.max(speed - tuning.braking, 0);
88	    const target = -divTrunc(tuning.maxReverseSpeed * -throttle, AXIS_SCALE);
89	    return speed > target ? Math.max(speed - tuning.reverseAcceleration, target) : Math.min(speed + tuning.drag, target);
90	  }
91	  return speed > 0 ? Math.max(speed - tuning.drag, 0) : Math.min(speed + tuning.drag, 0);
92	}
93	
94	/**
95	 * The nearest dock whose tile centre is within the dock radius of a position and that the hull can reach in a straight
96	 * line without touching land or a shoal, or undefined. Mooring moves the ship to that centre, so without the path
97	 * check it could cut a corner of land that sailing would have stopped it at.
98	 */
99	export function dockInReach(config: SimulationConfig, x: number, y: number): Dock | undefined {
100	  const reach = config.ship.dockRadius * config.ship.dockRadius;
101	  let best: Dock | undefined;
102	  let bestDistance = reach + 1;
103	  for (const dock of config.map.docks) {
104	    const centre = tileCentre(config, dock.tileX, dock.tileY);
105	    const distance = (centre.x - x) * (centre.x - x) + (centre.y - y) * (centre.y - y);
106	    if (distance < bestDistance && hullPathIsClear(config, x, y, centre.x, centre.y)) {
107	      best = dock;
108	      bestDistance = distance;
109	    }
110	  }
111	  return best;
112	}
113	
114	/**
115	 * The hull is a square of `hullHalfSize` around the position. It never overlaps a blocked tile, so a move only needs
116	 * to check the tile columns (or rows) its leading edge enters, in order: the first blocked one stops the hull flush
117	 * against it. However fast the ship, it cannot pass through a tile, so it never tunnels.
118	 */
119	function sweepX(config: SimulationConfig, x: number, y: number, dx: number): number {
120	  if (dx === 0) return x;
121	  const size = config.map.subUnitsPerTile;
122	  const half = config.ship.hullHalfSize;
123	  const top = Math.floor((y - half) / size);
124	  const bottom = Math.floor((y + half) / size);
125	  const blocked = (column: number) => {
126	    for (let row = top; row <= bottom; row++) if (!isNavigable(config.map, column, row)) return true;
127	    return false;
128	  };
129	  if (dx > 0) {
130	    const last = Math.floor((x + half + dx) / size);
131	    for (let column = Math.floor((x + half) / size) + 1; column <= last; column++) {
132	      if (blocked(column)) return column * size - 1 - half;
133	    }
134	  } else {
135	    const last = Math.floor((x - half + dx) / size);
136	    for (let column = Math.floor((x - half) / size) - 1; column >= last; column--) {
137	      if (blocked(column)) return (column + 1) * size + half;
138	    }
139	  }
140	  return x + dx;
141	}
142	
143	function sweepY(config: SimulationConfig, x: number, y: number, dy: number): number {
144	  if (dy === 0) return y;
145	  const size = config.map.subUnitsPerTile;
146	  const half = config.ship.hullHalfSize;
147	  const left = Math.floor((x - half) / size);
148	  const right = Math.floor((x + half) / size);
149	  const blocked = (row: number) => {
150	    for (let column = left; column <= right; column++) if (!isNavigable(config.map, column, row)) return true;
151	    return false;
152	  };
153	  if (dy > 0) {
154	    const last = Math.floor((y + half + dy) / size);
155	    for (let row = Math.floor((y + half) / size) + 1; row <= last; row++) {
156	      if (blocked(row)) return row * size - 1 - half;
157	    }
158	  } else {
159	    const last = Math.floor((y - half + dy) / size);
160	    for (let row = Math.floor((y - half) / size) - 1; row >= last; row--) {
161	      if (blocked(row)) return (row + 1) * size + half;
162	    }
163	  }
164	  return y + dy;
165	}
166	
167	/**
168	 * Whether the hull stays clear along the straight segment between two positions. It checks every position one
169	 * sub-unit apart along the longer axis, so between two checks the hull moves at most one sub-unit on either axis and
170	 * no tile corner can slip between them.
171	 */
172	export function hullPathIsClear(config: SimulationConfig, fromX: number, fromY: number, toX: number, toY: number): boolean {
173	  const dx = toX - fromX;
174	  const dy = toY - fromY;
175	  const steps = Math.max(Math.abs(dx), Math.abs(dy));
176	  if (steps === 0) return hullIsClear(config, fromX, fromY);
177	  for (let index = 0; index <= steps; index++) {
